#!/usr/bin/env bash
# Purpose: re-evaluate selected LoCoMo individual reports with the Mem0-style
# LLM judge prompt for GPT-4o-mini alignment checks.
# Runs: benchmark_locomo.task_eval.re_eval_llm_accuracy_triple.
set -euo pipefail

# LoCoMo10 LLM-judge alignment with the mem0 prompt.
# Evaluation model: gpt-4o-mini-closeai
# Output directories are auto-generated by re_eval_llm_accuracy_triple.py as:
#   <data-dir>/reeval_<timestamp>_<eval-model>_mem0
# No --output-dir is passed here, so existing benchmark outputs are not overwritten.

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$SCRIPT_DIR"
while [[ "$REPO_ROOT" != "/" && ! -d "$REPO_ROOT/src/mandol" ]]; do
  REPO_ROOT="$(dirname "$REPO_ROOT")"
done
if [[ ! -d "$REPO_ROOT/src/mandol" ]]; then
  echo "Could not locate Mandol repo root from $SCRIPT_DIR" >&2
  exit 1
fi
cd "$REPO_ROOT"

mkdir -p nohup_output/locomo_mem0_reeval

# 1. GPT-4.1-mini full tri-tower baseline.
nohup uv run python -m benchmark_locomo.task_eval.re_eval_llm_accuracy_triple \
  --data-dir benchmark_locomo/task_eval/results/locomo_tri_tower_ablation_gpt4.1/full_tri_tower \
  --model gpt-4o-mini-closeai \
  --llm-judge-prompt mem0 \
  --max-workers 1 \
  > nohup_output/locomo_mem0_reeval/gpt41_full_tri_tower_mem0_gpt4o_mini.log 2>&1 &

# 2. GPT-4o-mini dynamic adaptive routed aggressive cascade.
nohup uv run python -m benchmark_locomo.task_eval.re_eval_llm_accuracy_triple \
  --data-dir benchmark_locomo/task_eval/results/locomo_tri_tower_router_cascade_results_v2/gpt4o_mini_dynamic_adaptive_routed_aggressive_cascade \
  --model gpt-4o-mini-closeai \
  --llm-judge-prompt mem0 \
  --max-workers 1 \
  > nohup_output/locomo_mem0_reeval/gpt4o_dynamic_adaptive_routed_aggressive_cascade_mem0_gpt4o_mini.log 2>&1 &

# 3. GPT-4.1-mini dynamic adaptive routed aggressive cascade.
nohup uv run python -m benchmark_locomo.task_eval.re_eval_llm_accuracy_triple \
  --data-dir benchmark_locomo/task_eval/results/locomo_tri_tower_router_cascade_results_v2/gpt41_mini_dynamic_adaptive_routed_aggressive_cascade \
  --model gpt-4o-mini-closeai \
  --llm-judge-prompt mem0 \
  --max-workers 1 \
  > nohup_output/locomo_mem0_reeval/gpt41_dynamic_adaptive_routed_aggressive_cascade_mem0_gpt4o_mini.log 2>&1 &

# 4. GPT-5 default retrieval evaluated with GPT-4o-mini.
nohup uv run python -m benchmark_locomo.task_eval.re_eval_llm_accuracy_triple \
  --data-dir benchmark_locomo/task_eval/results/locomo_tri_tower_ablation_gpt5/default_retrieval_eval_gpt4o \
  --model gpt-4o-mini-closeai \
  --llm-judge-prompt mem0 \
  --max-workers 1 \
  > nohup_output/locomo_mem0_reeval/gpt5_default_retrieval_eval_gpt4o_mem0_gpt4o_mini.log 2>&1 &
